export const CAD_FAQ: { q: string; a: string }[] = [
  { q: "Je Mnástrojárna CAD opravdu zdarma a bez registrace?", a: "Ano. Otevřete mnastrojarna.cz/cad a modelujete. Žádný účet, žádná instalace, žádné omezení počtu dílů. Provozuje ho nástrojárna Mnástrojárna s.r.o.; výdělek máme z výroby dílů, kterou si u nás můžete rovnou poptat, ale nemusíte." },
  { q: "Umí otevřít soubory ze SolidWorks, Inventoru nebo ZW3D?", a: "Přímo nativní formáty (SLDPRT, IPT, Z3…) otevřít nelze – jsou uzavřené. Program vám u každého z nich ukáže, jak soubor ve zdrojovém CADu uložit jako STEP; STEP, IGES a BREP otevře s přesnou geometrií a lze na ně navazovat dalšími prvky (díry, zaoblení, přímé úpravy)." },
  { q: "Jak udělám výrobní výkres do PDF nebo DWG?", a: "Pás Výkres → Nový výkres. Zvolte pohledy a formát listu, doplňte kóty, drsnosti a tolerance tažením, případně řez a detail, a stiskněte PDF, DXF nebo DWG. U sestavy se přidá kusovník s pozicemi." },
  { q: "Zvládne sestavy a velké rámy forem?", a: "Ano – komponenty, podsestavy, vazby, kolize, kusovník, rozložený pohled a průvodce rámem vstřikovací formy s normáliemi. Komfortně zvládá sestavy o desítkách až stovkách komponent; výkon závisí na vašem počítači." },
  { q: "Jak vyberu myší více prvků naráz?", a: "Tažením obdélníku levým tlačítkem – ve 3D okně, ve skice, ve 2D výkresu i na výkresu dílu. Zleva doprava je okno (vybere jen to, co je celé uvnitř), zprava doleva křížení (i to, čeho se dotkne). Ctrl nebo Shift přidává, Ctrl+Shift nebo Alt odebírá, Esc zruší. Ve 3D se vybírají jen viditelné entity podle filtru výběru (Plocha, Hrana, Komponenta…); hrany pro zaoblení tak vyberete jedním tažením. Kdo chce levým tlačítkem otáčet, přepne to v Nastavení → Myš a ovládání → Levé tlačítko táhne." },
  { q: "Jak udělám pružinu a půjde použít v pohybu?", a: "Tvorba → Pružina: vyberete druh (tlačná, tažná, zkrutná, talířová), vyplníte pár řádků tabulky (drát, průměr, volná délka, závity) a CAD sám spočítá tuhost, délku na doraz, síly, napětí, vzpěr a hmotnost podle EN 13906 a postaví těleso jako skutečnou pružinu s broušenými konci. Do sestavy ji vložíte tlačítkem Sestava → Pružina mezi díly (klik na díru a protější plochu, i do všech děr vzoru najednou). V pohybové studii přepnete na Dynamiku – pružiny, gravitace a síly pak díly opravdu hýbou a výsledkem je graf, CSV a největší síla pružiny." },
  { q: "Jak vložím šroub M8×30 nebo profil IPE 200?", a: "Stiskněte Ctrl+L a napište „ISO 4762 M8x30“ nebo „IPE 200 1500“. Knihovna má 103 rodin normálií (šrouby, matice, podložky, kolíky, ložiska, ozubená a řetězová kola, řemenice, profily, pružiny, normálie forem, lineární technika, pneumatika, potrubí)." },
  { q: "Je rozhraní i v angličtině nebo němčině?", a: "Ano. Anglická verze běží na mnastrojarna.cz/en/cad, německá na mnastrojarna.cz/de/cad; přepnout lze také v Nastavení → Jazyk rozhraní (volba se pamatuje v prohlížeči). Přeložené jsou pás karet, formuláře, hlášky jádra, knihovna normálií, razítko výkresu i textové příkazy – konzole rozumí příkazům česky, anglicky i německy (např. „box 100 60 12“, „quader 100 60 12“). Dokumentace je zatím česky; stránky /en/cad/documentation a /de/cad/dokumentation shrnují ovládání." },
  { q: "Funguje na mobilu a tabletu?", a: "Ano. Nabídky a formuláře se na telefonu otevírají jako spodní listy, model otáčíte prstem, dlouhý stisk nahrazuje pravé tlačítko. Pro delší práci doporučujeme počítač nebo tablet s klávesnicí." },
  { q: "Funguje offline?", a: "Po prvním načtení běží výpočty i export lokálně v prohlížeči. Pro načtení aplikace a knihovny písem je potřeba připojení; rozpracovanou práci si ukládejte do souboru (ve výchozím režimu se v prohlížeči nic neuchovává)." },
  { q: "Kde jsou moje soubory uložené? Uvidí je někdo jiný?", a: "Jen tam, kam si je sami uložíte (.mncad, STEP, PDF…). Ve výchozím režimu CAD do prohlížeče nic neukládá – po zavření karty rozpracovaná práce zmizí, takže dokumentaci pod NDA neuvidí nikdo další ani na sdíleném počítači. Kdo chce obnovu práce a nedávné soubory, zapne šifrované úložiště s heslem; bez hesla jsou data nečitelná. Na server nic neposíláme – s výjimkou e-mailu, který sami odešlete tlačítkem Poptat výrobu, a sdílení odkazem, kdy na server jde jen kopie zašifrovaná už ve vašem prohlížeči." },
  { q: "Co znamená, že odkazy „přežijí změnu historie“?", a: "Když vyberete plochu nebo hranu jako cíl (např. vysunutí k ploše), program si uloží její otisk – typ, střed, velikost. Změníte-li dřívější prvek a plochy se přečíslují, odkaz se znovu najde podle otisku a prvek se nerozbije." },
  { q: "Jak zadám délku a úhel úsečky číslem?", a: "Ve skice stiskněte l, klikněte na první bod a začněte psát: 50, Tab, 30, Enter – vznikne úsečka 50 mm pod 30° i s kótou (je-li zapnuto Kótovat při kreslení). Fungují také zápisy 50<30, x;y a @dx;dy." },
  { q: "Umí plechové díly a rozvin?", a: "Ano – záložka Plech: základní plech, ohyby z hrany, lemy, ohyb podle čáry, výřezy, rohové úlevy, prolisy; Rozvinout a export rozvinu do DXF/SVG, tabulka ohybů." },
  { q: "Lze CAD použít komerčně a pro výuku?", a: "Ano, bez omezení. Výstupy (STEP, PDF, DXF, DWG) jsou vaše. Školy a kroužky vítáme – dokumentace a program jsou kompletně česky." },
  { q: "Jak poptám výrobu dílu?", a: "Tlačítkem Poptat výrobu v titulní liště: připraví se STEP aktuálního dílu a e-mail s předvyplněným předmětem. Vyrábíme prototypy, náhradní díly do jednoúčelových strojů, nástroje a přípravky, typicky 1–99 ks, včetně konsignace." },
  { q: "Co dělat, když prvek zčervená s chybou?", a: "Klikněte na prvek v historii – pod ním je česká hláška, co je špatně (např. příliš velký poloměr zaoblení, otevřený profil skici, cílová plocha za rovinou skici). Upravte parametr nebo výběr; ostatní prvky se přestaví automaticky." },
  { q: "Jak pošlu díl kolegovi nebo zákazníkovi, aby se na něj jen podíval?", a: "Tlačítko Sdílet (horní lišta) → Kopírovat odkaz, nebo rovnou WhatsApp / E-mail. Příjemce odkaz otevře v prohlížeči bez instalace – vidí snímek dílu, sestavy i výkresů, může měřit, řezat a uložit si kopii. Platnost nastavíte na 1–90 dní (výchozí 10), volitelně s heslem. Odkaz je krátký (mnastrojarna.cz/s# a deset znaků), dá se i nadiktovat. Dokument se zašifruje už v prohlížeči a na server jde jen šifrovaný obsah – klíč je v části odkazu za #, kterou prohlížeč na server neposílá. Modely nad 25 MB pošlete jako přílohu .mncad nebo STEP." },
  { q: "Program hlásí „3D okno nelze spustit“ – co s tím?", a: "Prohlížeč neposkytl WebGL (grafickou akceleraci), kterou 3D zobrazení potřebuje. Zapněte v prohlížeči grafickou akceleraci (Chrome/Edge: Nastavení → Systém; Firefox: Výkon) a restartujte ho, nepracujte přes vzdálenou plochu či virtuální stroj, aktualizujte ovladač grafiky, případně zkuste jiný prohlížeč nebo zařízení. Zbytek programu (nabídky, soubory, 2D skica, výkresy) funguje dál; tlačítko Zkopírovat diagnostiku připraví pro podporu údaje o prostředí bez dat dokumentu." },
  { q: "Může CAD ovládat AI agent (ChatGPT Agent, Claude) nebo skript?", a: "Ano. Nápověda → Textové příkazy (Ctrl+Shift+K): příkazy jako „kvádr 100 60 20“, „díra 8,5 skrz v 20 30“, „zaoblit 2 hrany svislé“ nebo rovnou JSON dokumentu; protokol vrátí ✓/✗ s důvodem a textový stav dokumentu (rozměry, objem, prvky), takže agent nepotřebuje číst obrázek. Pro skripty je k dispozici window.mncad (run, getDocument, setDocument, status). Návod a úplné schéma: /cad/schema-pro-ai.md. Výstupy (uložit, export step, výkres export pdf, sdílet) jdou zadat textem bez systémových dialogů. Pro člověka se nic nemění." },
  { q: "Proč výkres neuvádí ISO 2768 ani sražení hran? Dříve tam byly.", a: "Výrobní požadavky jsou konkrétní technické údaje, které by na výkres neměly přijít bez vědomí konstruktéra. Výkres proto standardně uvádí jen „Rozměry v mm“; nepředepsané tolerance (např. ISO 2768-mK) a opracování hran (např. srazit 0,5×45°) vyplníte v razítku – každé zvlášť, kdykoli lze smazat. Tlačítko „Doplnit obvyklé“ je vyplní jedním klikem. Nepředepsané tolerance se vybírají třídou ISO 2768 nebo tabulkou podle počtu desetinných míst; výkres dílu bez nich panel Razítko označí ⚠ a export to ohlásí." },
  { q: "Jak dostanu do razítka materiál jako „ČSN 11 423“, když v nabídce je jen Ocel, Nerez…?", a: "Nabídka Materiál určuje třídu (hustotu) pro hmotnost. Pod ní je pole „Označení materiálu (razítko)“ – volný text, který se uloží do dokumentu, přenese sdíleným odkazem i souborem .mncad a zobrazí v razítku výkresu. Stejné pole je přímo v razítku výkresu. Textový příkaz „materiál ČSN 11 423“ dělá totéž a protokol napíše, podle které třídy se počítá hustota." },
  { q: "Prvek je zelený, ale model se nezměnil / STEP se nedá uložit. Proč?", a: "Stav prvku má oddělené úrovně: přijetí příkazu (šedé → „… – výsledek po výpočtu níže“, to ještě není výsledek), vznik prvku, účinek operace proti nástroji (např. „úběr 352,1 mm³ (>99 % nástroje)“) a konečné těleso („těleso platné“ / „těleso nezkontrolováno (důvod)“). Úprava, smazání nebo změna proměnné je nejdřív jen přijatá; ✓ / ⚠ / ✗ přijde po přepočtu na řádku té úpravy a řádek s chybou nikdy nemá zároveň ✓. Velké těleso, jehož platnost se nekontrolovala, není zelené – ve stromu prvků má šedý otazník a v protokolu ℹ. Načtený dokument (soubor, JSON) je také nejdřív jen přijatý; „dokument … postaven: prvků N, bez ⚠ a ✗“ se vypíše až po ověřovací stavbě. Po každém prvku program porovná objem a topologii tělesa a zkontroluje platnost geometrie (BRepCheck); prvek, který má dát objemové těleso a dá jen plochu nebo plášť, skončí červeně. Prvek, který těleso nezměnil (nástroj mimo těleso), nebo jehož výsledek má sebeprotínající plochy, dostane oranžové ⚠ s vysvětlením v historii, ve formuláři i ve stavovém řádku; operace, kterou jádro neprovede (např. skořepina přes zaoblené plochy), skončí červeně a těleso zůstane. Varování o neplatné geometrii stojí u prvního prvku, který ji způsobil, a jmenuje vadnou hranu nebo plochu; prvky za ním odkazují na něj („Těleso je neplatné už od prvku …“). Stav dokumentu (konzole „stav“) má řádek Geometrie: platná / neplatná / bez objemového tělesa." },
  { q: "Jak udělám jemný závit M18×1,5 nebo závit v díře?", a: "Prvek Závit přijímá hrubé i jemné stoupání (nabídka nebo text „M18×1,5“); zaškrtnutí Vnitřní závit (v díře) ho umístí do díry (kružnice jádra se pak kótuje M18×1,5). Díra se závitem má stejnou nabídku a jádro dopočítá. Skutečnou šroubovici dá Plochy → Tažení po šroubovici: profil Závit 60°, volba Vnější (na válci) / Vnitřní (v díře), poloměr = povrch, kde závit začíná, hloubka jde do materiálu; Náběh (otáček) vybrousí hřbet prvního závitu jako u závitového kalibru – od začátku až na dno drážky, během zadaných otáček se zvedá do plného profilu. Na výkrese se modelované závity kreslí zjednodušeně podle ISO 6410 – hladký válec / díra s označením M18×1,5 (přesná projekce šroubovice by trvala minuty); ve STEP je skutečná šroubovice." },
  { q: "Jak zadám skutečnou šroubovici z označení závitu a jak poznám, že drážka řeže povrch?", a: "Ve formuláři prvku Závit zvolte Provedení: Kosmetický (jen výkres), Drážky (zjednodušeně, bez stoupání) nebo Šroubovice – skutečná šroubovice z označení (M18×1,5), se stejnými čísly jako Tažení po šroubovici s vyplněným polem Závit z katalogu. Textem: „závit M18×1,5 délka 20 šroubovice“ (označení smí mít i mezery: „m18 x 1,5“). Stoupání mimo řadu ISO 261 (např. M18×3) se postaví, ale prvek dostane ⚠. Program ověří, že drážka řeže válec nebo díru: tečná špička profilu, drážka celá v materiálu (skrytý kanál) nebo drážka obrácená ke stěně jen špičkou dají ⚠ s radou, jakou stranu a poloměr zadat. Platnost tělesa po stavbě je rychlá kontrola – ve stavovém řádku je čip „platné · rychlá kontrola“; kliknutím (nebo příkazem „kontrola přesně“) spustíte přesnou kontrolu. Před exportem STEP do 400 ploch proběhne přesná kontrola sama a export model nijak neupravuje." },
  { q: "Stačí automatické kótování pro výrobní výkres?", a: "Ne – „Auto + Ø“ je pomocný základ (celkové rozměry, průměry děr, závity). Funkční kóty, tolerance (H8, g6, ±0,1) a drsnosti doplní konstruktér – tolerance z geometrie odvodit nelze. Tlačítko „Kontrola kót“ ve výkresu porovná kóty na listu s historií prvků (u rotačních dílů průměry a délky osazení, závity, drážky, zaoblení; délka průchozího řezu se nenabízí) a vypíše, co chybí; toleranci zapíšete u kóty do pole „přípona“. Poznámka „Nekótované rozměry dle 3D modelu“ se na výkres nedoplňuje sama – zapnete ji v razítku (Poznámka v patičce)." },
  { q: "Umí otevřít a upravit výkres DWG nebo DXF jako AutoCAD?", a: "Ano. Soubor DWG (R2000–R2018) nebo DXF (R12–R2018) přetáhněte do okna nebo otevřete přes Ctrl+O – načte se jako 2D výkres s hladinami, bloky, kótami a rozvrženími. Kreslíte a upravujete příkazovým řádkem (čára, kružnice, oříznout…, i zkratkami L, C, TR) nebo myší, s uchopením, ORTHO, hladinami a typy čar; přidáte kóty, šrafy a texty, vytisknete do PDF v přesném měřítku a uložíte zpět do DWG nebo DXF ve zvolené verzi. Externí reference (XREF) se nenačítají a písma SHX se kreslí nejbližším webovým písmem. Návod je v kapitole 14 dokumentace." },
  { q: "Je krátký sdílený odkaz bezpečný? Co je uloženo na serveru?", a: "Na serveru je jen dokument zašifrovaný už ve vašem prohlížeči (AES-256). Klíč se odvozuje z desetimístného kódu, který je v odkazu za znakem # – tu část adresy prohlížeč na server nikdy neposílá, takže server obsah nepřečte; po vypršení platnosti (1–90 dní) nebo po zneplatnění ho smaže. Kód má přibližně 4 × 10^17 kombinací, jeho zkoušení brzdí záměrně pomalý výpočet a limit dotazů. Platí ale, že kdo má odkaz, dokument otevře: pro citlivou dokumentaci přidejte heslo, pošlete ho jinou cestou a zvolte krátkou platnost. Kdo nechce na server posílat ani šifrovaná data, zvolí v dialogu „jen v odkazu (bez serveru)“." },
  { q: "Jde CAD spustit bez prohlížeče – ze skriptu nebo na serveru?", a: "Zčásti. Příkazová řádka mncad (Node.js 22 nebo novější, balík na /cad/cli/) dnes bez prohlížeče otevře hotový dokument .mncad, postaví ho ve stejném jádře a zapíše STEP, STL a výkresy PDF, DXF, DWG a SVG; vypíše stručný protokol s objemem a hmotností a vrátí kód ukončení – hodí se pro dávkové převody a kontrolu v CI. Provádět textové příkazy (modelovat skriptem) zatím umí jen aplikace v prohlížeči; tu lze řídit automatizací (Playwright, Selenium) i bez grafické karty a výstupy z ní dostat bez dialogů. Podrobnosti v kapitole 22 dokumentace." },
  { q: "Co jsou bubliny u ikon a dají se vypnout?", a: "Mikronávody: po najetí myší na ikonu pásu karet (na dotyku dlouhým stiskem) se ukáže, co příkaz dělá, kdy ho použít, co vybrat, postup v několika krocích a tip; u neaktivního tlačítka i důvod, proč nejde použít. Jsou česky, anglicky i německy. Vypnete je v Nastavení → Obecné → Mikronávody u ikon." },
  { q: "Jak udělám otvor střižnice s břitem a odlehčením?", a: "Jedním vysunutím: skica otvoru na střižné ploše, Odebrat, Skrz vše, v pokročilých volbách Úkos 2° se stranou Ven a Břit 3 mm. Otvor má prvních 3 mm rovné stěny a pod nimi se rozšiřuje o 2°, takže výstřižek volně propadne. Textem: „vysunout skrz odebrat obráceně úkos 2 ven břit 3“." },
  { q: "Jak převedu hotový model na textové příkazy?", a: "Data → Export → Textový skript (.txt), v konzoli příkaz „export skript“, pro skripty window.mncad.script(). Vznikne soubor .mncad.txt se stejnými příkazy, jaké se píší do konzole Textové příkazy – díly, skici, prvky, proměnné, sestava s polohami a vazbami, pohybová studie a výkresy. Vložený do konzole postaví tentýž model v nové záložce. Ruční kóty výkresu, komponenty z importovaných souborů a podsestavy se nepřenášejí; protokol exportu vypíše, co chybí. Podrobnosti v kapitole 22 dokumentace." },
  { q: "Jak zkontroluji model podle výkresu zákazníka v DWG nebo PDF?", a: "Připojte výkres jako předlohu: v konzoli Textové příkazy tlačítkem Připojit soubor… a příkazem předloha \"výkres.dwg\" (DWG, DXF nebo vektorové PDF). Příkaz porovnat předloha pohled přední položí promítnutý model přes pohled předlohy a vrátí pokrytí v procentech a odchylky s polohou, předloha kontrola kót změří kóty předlohy v modelu (✓ / ✗). Už při připojení CAD upozorní na rozpory v předloze, např. kótu, jejíž text neodpovídá nakreslené geometrii. Podrobnosti v kapitole 15 dokumentace." },
  { q: "Prvek má ⚠ „Výsledek operace neodpovídá průniku tělesa s nástrojem“. Co s tím?", a: "Nástroj je téměř tečný k ploše tělesa nebo končí přesně na jeho hraně – typicky souřadnice opsané z výkresu na 4–6 desetinných míst. Kontrolní výpočet (opakování s malou tolerancí nebo průnik tělesa s nástrojem) dal jiný objem než přesná operace, proto program ponechal přesný výsledek a prvek označil; hláška uvádí obě hodnoty v mm³. Posuňte nástroj tak, aby plochy tělesa jasně protínal (aspoň o 0,01 mm), nebo aby s nimi splýval přesně; rovinu skici zadejte úhlem nebo odkazem na plochu místo zaokrouhlených vektorů." },
];

